"""Author the complete current DE4 draft and finite cases; preserve all originals and approvals."""
from copy import deepcopy
from datetime import datetime,timezone
import json
from apply_di7_ap_as_01 import G,R,A,info,encoded
from prepare_ac5_current_interfaces_01 import at

def read(p):return json.loads(p.read_bytes())

def main():
    out=R/'data/director/spell_proposals/divination_enchantment_rank4_current_02.json'
    report=A/'DE4_CURRENT_PROCEDURES_CHECK_02.json';assert not out.exists() and not report.exists()
    auditp=A/'DE4_CURRENT_SOURCE_INTERFACE_AUDIT_01.json';audit=read(auditp)
    amendp=A/'DE4_FATE_GUARD_AMENDMENT_DRAFT_02.json';amend=read(amendp)
    checks=[]
    def ck(name,passed):checks.append({'name':name,'passed':bool(passed)});assert passed,name
    sources={b['path']:b for b in audit['sourceBindings']}
    for b in amend['sourceBindings']:sources[b['path']]=b
    for p in [auditp,amendp,A/'DE4_CURRENT_SOURCE_INTERFACE_CHECK_01.json',A/'DE4_FATE_GUARD_AMENDMENT_CHECK_02.json']:sources[p.relative_to(G).as_posix()]=info(p)
    for b in sources.values():ck('Current source remains exact '+b['path'],info(G/b['path'])==b)
    index=read(R/'data/public/spell_playtests/authored_review_index.json');ck('451/397 unchanged',index['authoredCounts']=={'reviewed':451,'pending':397})
    records=[]
    for row in audit['records']:
        old=row['completeHistoricalProposal'];records.append({'spellId':row['spellId'],'questionId':row['questionId'],'completeSourceAndAccess':deepcopy(row['completeCurrentSourceAndAccess']),'originalQuestion':old['originalQuestion'],'historicalProposalUnchanged':deepcopy(old),'procedure':old['procedure'],'status':'Complete current local proposal, UNSENT and UNADOPTED; actual joint review and pending AC6 dependency refresh required.'})
    byid={s['spellId']:s for s in records};edits=[]
    def append(ident,value):byid[ident]['procedure']+='\n\n'+value
    def replace(ident,before,after):
        old=byid[ident]['procedure'];ck('Unique correction anchor '+ident,old.count(before)==1);byid[ident]['procedure']=old.replace(before,after,1);edits.append({'spellId':ident,'before':before,'after':after})
    shared=deepcopy(audit['historicalSharedProposalUnchanged'])
    shared['status']='NEW complete current local DE4 proposal only; original shared proposal retained separately. No adopted rule or source is changed.'
    old_info=shared['information'];shared['information']=old_info.replace('The pending expedition reputation verdict is not presumed.','Current accepted expedition/faction procedures now supply their actual records and social limits. This spell proposal grants no membership, standing, allied status, permission, roster or institution merely by requesting information.')
    ck('Historical pending expedition wording refreshed',shared['information']!=old_info)
    shared['DE4-GUARD-01']=amend['proposedGuardVerbatim']
    shared['DE4-SEAL-LOCI-02']='NEW spell-specific proposal for Seal Vision only. In creature mode use the protected actual body; in area mode a body is protected when any actual portion is within the20ft sphere and has center LoE, and a discrete spatial magical expression is protected at its actual source-defined locus. No whole-plane, body-independent soul or remote caster concentration locus is inferred. For an ongoing body-target Divination buff/mark, suspend that target component while protected, preserve identity/deadline/history, and resume only a still-existing component when protection ends. For a pending personal Divination permission, an actually protected/suppressed holder cannot activate that permission. For a Divination-created Fate Coin inside the area, retain the actual same physical coin/HP/custody/deadline while disabling its magical reroll use; do not create material or destroy it merely from this spell suppression. Prevent an actually blocked new Divination component from establishing; no deferred component appears when protection later ends. For a reroll use whose own source remains operative, separately test the actual original roll-generating creature/object or source-defined local event. Protecting one recipient of an independently generated shared damage pool does not split or selectively reroll that pool, and ordinary indirect consequences retain their original source school. The original roll generator/event is fixed by the actual source before a reroll; it is not the physical tabletop die position or a convenient alternative victim. If a source leaves that generator genuinely undefined, resolve and record that ambiguity before claiming a legal protected/unprotected example. Known non-operative permission is unusable without expenditure. An otherwise legal operative permission committed against a protected original roll event is spent under its real source and common guard, but its blocked Divination alteration produces no replacement; the unchanged original result resolves. This latter paid-block distinction is explicit NEW local authorship requiring joint review. No information-only ward becomes general antimagic.'
    shared['DE4-ORDER-DELIVERY-02']='NEW scoped Dominate Person mental-order channel: a conscious controller can issue the one opportunity order only while controller and target are on the same actual plane. No additional maintained range or shared language/hearing is required; no perceptions/location/knowledge flow back. Protection against an actual information-gathering source does not by itself cancel this noninformational channel. A genuinely issued valid order retains its ordinary opportunity and exact expiry if the target is subsequently relocated; a later failed new issuance creates no replacement. This does not transport the target, permit an unsafe route or compel optional resource use. Dominate Person uses the future START/actual attached-phase opportunity, so it does not grant an advance stored order outside those specific source timings. Compulsion stores a fixed world-space direction on its actual application plane. If the target is on another plane at its sole execution opportunity, the direction instruction has no executable route and expires without refund or delayed retry; no universal cross-plane compass relation is invented. Same-plane relocation keeps the recorded world direction, not a new vector to the caster.'
    shared['DE4-NIGHTMARE-ROOT-02']='NEW source-specific implementation of the accepted Null root rule. On a failed Phantasmal Killer application with a legally established damage component, create that recipient/application damage root before its first packet and snapshot the actual caster dealer\'s current unsuppressed Null Veil. The Illusion immediate packet and all later scheduled packets of that application descend from this one root, even if its initial round exposure was already spent and no initial packet resolved. Later Veil changes never rewrite this root. A genuinely new spell application, including a separate Enchantment immediate hit, creates a new root and checks the then-current caster state. Allocating a root is not damage, a hit, a Wound, a kill, a resource event or a claimed periodic exposure. Use actual scheduled recipient lifecycles, death saves and preexisting-source timing; a companion phase is not a new regular turn.'
    append('fate-reversal','CURRENT SHARED-RULE AMENDMENT: This procedure is conditional on explicit joint approval of DE4-GUARD-01 and the complete nine-file amendment draft. The previously accepted two-spell guard is not silently changed by this local proposal. Use the complete original attack/save/check d20 procedure; an automatic success/failure without an actual roll supplies no d20 event to replace. Fate Reversal is not limited to one physical die like Fate Coin, and adds no information about hidden rolls. No source permits choosing a favorable subset of advantage/disadvantage dice. If the personal permission is actually suppressed, no use is legal; if an operative use commits but a protected event blocks its Divination alteration under DE4-SEAL-LOCI-02, record its real spent permission/Reaction/guard and retain the original result.')
    append('seal-vision','NEW LOCUS COMPLETION: Apply DE4-SEAL-LOCI-02 in full. This distinguishes protecting the operator\'s pending Divination permission, the actual affected target component, and the original event that a still-operative reroll attempts to change. Do not selectively change a shared roll for only unprotected recipients or turn its unchanged non-Divination damage into a blocked Divination attack. The existing same-family Seal exemption prevents mutual shutdown; independent areas keep their own original clocks. The proposed area/body-intersection and retained Fate Coin physical-body handling are explicit new choices, not historical source facts. AC6 Globe/Alignment Nexus remains under actual review; its pending manuscript grants no assumed combination or automatic exemption here.')
    append('aspect-of-insight','CURRENT SOURCE TIMING: Apply the plus2 INT/WIS score and mental-save advantage only while this application is operative. An applying condition/spell DC already recorded by its source remains that recorded DC; a genuinely new cast computes its actual current ability modifier. Each printed class resource is read by its own acquisition/recovery timing. For example Druid Buffer Reserve is recorded after a beneficial Long Rest as2L+M; this temporary spell alone neither repeats that rest nor changes a previously recorded reserve. Class limits explicitly using a current modifier can change only within their actual wording. Do not convert every appearance of M into a new dynamic maximum, prepared slot or learning entitlement. Rising maxima give no refill; a real falling dynamic maximum uses only the accepted cap rule without damage/resource-gain triggers. Duplicate advantage remains one advantage, and any actual disadvantage cancels it under Core regardless of source count.')
    append('locate-creature','CURRENT PLACEMENT-CONFLICT INTERFACE: Ordinary Banishment\'s active cell is genuinely another scoped location/plane for this sensing test; no special five-mile shortcut detects its occupant through that cell. After that cell actually ends, a still-existing body in BAN-CONFLICT-04 has its recorded origin-plane AnchorReference for source range/predicate tests even though it has no occupied footprint. This spell\'s explicitly remote same-plane snapshot may return bearing to that reference when all its own actual information permissions are met. It grants no footprint, path, sight, physical targetability exception, support or placement resolution; the target\'s real conflict and clocks persist. Apply the same exact bridge only to AC5 exiles where AC5-BANISH-EXT-01 actually extends it. Corpses remain ineligible here, and a source-ended summon has no surviving identity to locate.')
    append('faction-secrets','CURRENT FACTION BOUNDARY: Accepted expedition reputation and faction records are current sources; older pending-verdict wording is historical. Membership, standing, alliedStatus, invocation permission, public/institutional knowledge and a person\'s protected private information remain distinct inputs. No representative or standing prerequisite is added to this proposed Self inquiry merely because companion invocations have such gates. A returned fact neither grants a credential nor changes an actual ledger. A protected personal memory is not reclassified as an institutional document to evade Protection from Scrying/Seal Vision. Record the stable subject/query key and established fact selected, preserving later genuine changes instead of treating rewording or a different caster as a new secret lottery.')
    append('alignment-forecast','CURRENT ALIGNMENT INTERFACE: In each genuinely supported predicted interaction, evaluate its own actual time and source timing. For a current effective read, use accepted AP-AS-01 underlying history then earliest eligible active AC4 Lock/Anchor per locked axis last. For a source that already took an immutable alignment snapshot, use that recorded snapshot, not a retroactive current value. Known fixed expiries can be considered; unknown voluntary choices and undefined axes are not invented. The result states only the specified material alignment contribution to the concrete stated goal, with no hidden cause or protected identity disclosed. Pending AC6 Nexus does not supply an approved plane-wide benefit or transport classification for a worked example.')
    append('resonance-divination','CURRENT PAYMENT CHECKPOINT: Identify the target\'s actual ordinary shared RP ledger, if any, after all earlier committed events have resolved. An actual RP expenditure preceding this read is reflected once, but RC/item charges and companion-owner accounts are not automatically merged. Temporary RP is included only when its source really inserts it into that same spendable ledger; absent source text is not permission to invent a pool. Current zero is a readable numeric fact distinct from no readable pool. Actual information protection applies to this Divination read without exposing why it failed; the original cast still spent its lawful cost. Preserve the existing lower-rank Resonance Sight exactness and discuss this source\'s distinct reach/value openly.')
    append('dominate-person','NEW ORDER DELIVERY: Apply DE4-ORDER-DELIVERY-02. Same-plane conscious one-way issuance grants no location/senses or cross-plane mental network. Eligibility was actual Humanoid at application only; later identity-preserving body change does not silently replace it. A new cast may replace the old controller only after its own failed-save hard component genuinely establishes with an unspent eligible source-character/target/encounter guard. A saved, immune, suppressed-before-establishment or guard-blocked cast replaces nothing and never refunds old history. The companion bridge uses original owner structure and a same-companion/same-phase pending reservation only; no caster creates an unwilling owner BA or steals another companion\'s reservation.')
    append('mass-pacify','NEW ENDING CHECKPOINT PRECISION: An actual later legal attack against the pacified target must reach its source\'s committed-attack event; a rejected preflight declaration is not an attack and creates no ending. Once a qualifying attack commits, this application ends even if that attack later misses or an actual interrupt prevents its damage. An already committed attack predating application does not retrospectively qualify. A voluntary self-attack is not an attack by any other creature under the printed ending predicate. Nonattack saving-throw damage remains permitted by this deliberately narrow attack-only restriction; that is an explicit rank/value decision for joint review, not a general friendly-behavior rule. Capture the caster\'s actually identified enemy set once after relevant interruptions; later hidden allegiance or field entry creates no new target.')
    append('confusion','NEW FINITE DRAW COMPLETION: Declare each actual table/direction/target draw method before drawing. The behavior d4, any required d8 direction and the chosen-target1dN are separate original roll events, each resolved with its own actual visibility and applicable guard before later consequences. Sort eligible perceived other-creature identities by stable existing ID; no hidden creature enters this source\'s perceived-only attack set. A replacement of one eligible physical die uses the same preexisting set, not a newly favorable candidate list. A digital draw does not automatically satisfy Fate Coin\'s physical-die requirement. If N=0, no target draw or substitute occurs. The direction branch spends an ordinary movement budget capped at half actual current Speed, with strongest terrain rate1/2/3 plus actual crawl/squeeze additions; it grants no additional Speed, support or second movement budget. Full establishment spent the hard guard even when a later table gives ordinary agency.')
    replace('erase-emotion',"Mooncursed’s nonfear body/bite/healing functions", "Mooncursed’s nonfear body/bite and actual temporary-HP Howl choice")
    append('erase-emotion','CURRENT COMPONENT BINDINGS: Actual Druid Mooncursed /cards/27 has no independently maintained rage-state record merely because its original prose says Lunar Rage. Its ordinary resistance, bite, real full-moon bonus and temporary-HP Howl choice remain; the actual fear Howl choice is prohibited, with no invented healing. An actual legal temporary-HP Howl still pays its Form Surge and full Buffer Reserve offer and retains once-per-shift history. Oracle Divine Fury /cards/108 still pays2RC and supplies its actual nonfear attack/DR/BA benefits; only its critical-hit Frightened output is prevented. Oracle Fury of the Host /cards/111 remains its own full actual effect; its title is no rage classification. Warrior Intimidating Presence /cards/8 is wholly fear-output and has no legal activation while prohibited; no Action or recharge commits for that known invalid preflight. An independently inflicted existing fear on another creature is not erased by suppressing the original actor\'s future output.')
    append('compulsion','NEW PLANE AND MOVEMENT COMPLETION: Apply only the Compulsion clause of DE4-ORDER-DELIVERY-02. Its one fixed direction is recorded on the actual application plane. At the one future opportunity, cap the spendable ordinary movement budget at30feet and at the actual remaining allowed budget. Use real terrain/crawl/squeeze cost per foot; this does not promise30feet of path through arbitrary difficult geometry. No paid Dash, teleport, owner BA, unsupported step or fresh action is supplied. If the actual source plane, legal route, support or available movement is missing, perform only a lawful possible portion and consume the sole opportunity. No crossing to another plane creates a new compass system or postpones execution until return.')
    append('phantasmal-killer','CURRENT DAMAGE ROOT AND LIFE ORDER: Apply DE4-NIGHTMARE-ROOT-02. Illusion\'s later packets retain the root created on its failed-save damage-component establishment; caster purge or suppression after that moment cannot make those old packets newly lethal. A genuinely new Enchantment cast takes a new root snapshot. Positive damage under Null still triggers actual damage-sensitive saves/endings elsewhere. A target already at0 resolves an actual regular-START death save before this later spell START packet under Core. A companion-only phase creates no new death save. The Illusion round-family exposure is consumed only by the source\'s scheduled opportunity rules; prevention/suppression cannot bank a replacement pulse. Normal source duration, source-ended summons, terminal death and concentration end remain real, with no corpse, deleted body or prior application recreated.')
    append('charm-monster','CURRENT DAMAGE AND SOCIAL BOUNDARY: Observe one actually resolved positive post-defense/pre-temp packet, preserving its original root through pure transfers and observing exact prevention before deciding positivity. Absorption by temporary HP does not erase a positive qualifying packet; a pure prevention pool that reduces the packet to0 gives no damage-triggered save. Null nonlethal damage remains damage and can trigger this save. Use what this particular target actually recognizes then as the caster\'s ally, not guessed faction alliedStatus, membership, remote roster or the friendliness this spell itself supplied. A save/end of one caster relation changes no other caster\'s independent relation, memories or actual social ledger; Charmed never supplies consent for an unrelated spell or contract.')
    append('overwhelming-grief','CURRENT ENDING AND IMMUNITY BOUNDARY: A legal positive post-defense/pre-temp damage packet ends this application even when temporary HP absorbs it or Null changes its later lethal endpoint. Actual zero after pure prevention does not. An attack\'s already determined hit/critical outcome is not rerolled because grief ends afterward. If initial actual Incapacitated is prevented by immunity or spent hard control, no application or deferred emotion substitute establishes. Real class exceptions can prevent only the components their actual text names; no spell title grants a blanket concentration exception. When an established application ends, lost concentration and spent commands/resources stay lost. Source-only END save timing adds neither an owner phase nor ordinary death-save/recharge processing.')
    examples=[]
    def case(ident,title,state,steps,cost,clocks,geometry,outcome,issues):
        n=len(examples)+1;refs=[{'path':out.relative_to(G).as_posix(),'pointer':'/spells/'+str(records.index(byid[ident]))+'/procedure'}]
        for issue_id in issues:
            issue=next(x for x in audit['currentReviewIssues'] if x['id']==issue_id)
            for ref in issue['sourceRefs']:
                if ref not in refs:refs.append(ref)
        examples.append({'id':f'DE4-N{n:02}','spellId':ident,'title':title,'initialState':state,'actionsAndResolution':steps,'costLedger':cost,'clockLedger':clocks,'geometryLedger':geometry,'outcome':outcome,'sourceRefs':refs,'status':'Complete local authored adjudication example under explicitly proposed DE4 rules; actual joint review, runtime and human validation remain open.'})
    base={'ordinaryRank4BaseRp':7,'actualClassAccessAndRepertoireRequired':True,'noAssumedDiscountOrPoolGrant':True}
    case('fate-reversal','One guard for one whole advantage attack','Caster A has an operative unused Fate Reversal at t0, expiring60, actual available Reaction. Another caster B has a legal Mark Omen on targetT. B makes its own legal advantage attack at t6; visible faces[4,17],modifier+7,T AC18. Both source preflights are legal; B has earlier actual initiative.', ['B commits Mark Omen first with no extra Action/Reaction and reserves DE4-GUARD-01. Replace both d20s with[6,9],select9,total16,miss.', 'A\'s later declaration against the same original/replacement lineage is barred before payment: permission and Reaction remain. No second full pair is rolled. B\'s ammunition/original attack cost was paid only once.', 'A later separate eligible d20 event before60 can use A\'s permission normally; the rejected declaration neither resets nor extends it.'],{**base,'markOmenUse':1,'fateReversalUse':0,'fateReversalReaction':0},{'permissionCreated':0,'expires':60,'attack':6},{'A_to_rollGeneratorB':30,'clearLoE':True},'The proposed common guard prevents competing sources from rerolling the same original event twice.',['DE4-C01'])
    case('fate-reversal','Shared damage and generator protection','An operative Fate Coin holder H is outside Seal Vision and perceives Wizard W at20ft clearLoE. W, also outside Seal, casts actual Burning Hands and its public shared3d6 fire roll is[2,4,6]. Two failed-save recipients are in the cone; only recipientR1 is inside Seal Vision. Neither is otherwise fire-resistant.', ['Fate Reversal cannot alter this damage roll at all; it is not an attack/save/check d20, so no Reversal permission or Reaction commits.', 'Under the proposed Seal locus rule, the actual roll-generator W is unprotected; protecting R1 does not recategorize the original Evocation damage or split the shared roll.', 'H uses the actual Coin Reaction, replaces the2 with5 and recomputes shared total15. Both failed-save recipients take the same15 before their own defenses; no separate reroll was made for R2. The Coin guard covers that damage event only.'],{**base,'fateReversalUse':0,'fateCoinUse':1,'H_Reaction':1},{'damageReroll':'before any damage consequences'},{'H_to_W':20,'coneTargets':2},'Fate Reversal eligibility and a protected recipient do not manufacture per-target shared damage results.',['DE4-C01','DE4-C02'])
    case('seal-vision','Body intersection, remote caster and real suppression','Seal Vision area center(0,0),radius20,deadline60; its caster is at(30,0). Medium T has a five-foot footprint and center(21,0), with part of body inside and centerLoE. T has one still-live Divination Aspect buff and a separate non-Divination Spell Resistance buff.', ['T is protected by this proposed any-body-intersection rule. Its Aspect component is suspended; Spell Resistance remains unless another actual suppressor covers it.', 'Move T to(23,0),entire footprint outside. The still-live Aspect resumes for its original remaining duration; neither source re-casts or refills a stat/resource.', 'In an independent branch the remote Seal caster steps into a separate Antimagic field at(40,0) that reaches neither the Seal area expression nor T. Caster entry alone does not globally suppress the distant Seal. Actual affected loci still govern.'],base,{'sealDeadline':60,'buffDeadlines':'unchanged'},{'T_beforeCenter':[21,0],'T_afterCenter':[23,0],'bodyWidth':5},'Geometry is explicit and remote concentration ownership is not an invented global suppression channel.',['DE4-C03'])
    case('seal-vision','Protected operator versus protected original event','H holds a physical live Fate Coin AC10HP1 with deadline3600, inside an operative Seal area. A separate Fate Reversal caster F is outside all Seals with an operative permission until60 and available Reaction. Creature G inside Seal generates a public actual d20 check, face12+3=15.', ['H\'s Coin use is unavailable while its magical expression is suppressed. It remains the same physical coin,HP1,custody and deadline; no use/Reaction/guard commits.', 'F perceives G within30ft clearLoE and satisfies its own Reversal preflight. If F legally commits to this protected original event under the explicit proposed paid-block rule, permission/Reaction/common guard are spent but the Divination alteration is blocked: retain original12+3=15,with no replacement dice.', 'Overlapping Seal fields do not suppress one another. Ordinary observers and independent readable surroundings are unaffected; no hidden cause/roster is reported by a blocked magical inquiry.'],{**base,'H_coinUses':0,'H_Reactions':0,'F_permissionUses':1,'F_Reactions':1},{'coinDeadline':3600,'reversalDeadline':60},{'F_to_G':30,'clearLoE':True},'This is a NEW explicit paid-block/locus adjudication for joint review, not an assumed earlier guard rule.',['DE4-C02','DE4-C03'])
    case('aspect-of-insight','Cap20 and an actual rest-snapshotted reserve','Druid10 has current INT19,WIS21,M5 and a Buffer Reserve already recorded after its last beneficial Long Rest at2*10+5=25,currently17. An eligible caster applies Aspect; no rest occurs.', ['INT becomes20,modifier+5 instead of+4. WIS21 is not reduced and gets no increase; its modifier remains+5.', 'Current Buffer remains17 and the recorded rest snapshot remains25. No shift use, Form Surge, prepared spell, permanent prerequisite or repertoire is granted.', 'On expiry INT returns19; no HP damage/healing, RP refund or repeated rest happens. WIS and the existing reserve stay unchanged.'],base,{'durationSeconds':60,'restEvents':0},{'targetWithin60':True,'clearLoE':True},'The source grants a temporary score bonus, not a recovery event.',['DE4-C04'])
    case('aspect-of-insight','New-cast DC versus existing applying DC','Wizard7 has INT18/PB3,spell DC15,mental save advantage from one independent valid source, and an existing spell application that recorded DC15. Aspect raises INT20; WIS is below20. A second equal Aspect exists from another caster.', ['Identical flat score bonuses do not add to+4: effective INT20,modifier+5. A genuinely new eligible spell uses DC16; the old application\'s recorded DC15 is unchanged.', 'Mental-save advantage remains one advantage. An actual disadvantage makes one ordinary d20 roll despite two advantage sources.', 'Suppress one of the equal Aspect applications while the other remains operative: no stat drop. When both are inactive/ended, INT18 returns. No new prepared slot, spell knowledge or automatic pool refill was granted.'],base,{'oldDcSnapshot':15,'newCastDc':16,'eachDeadline':'original'},{'sameWillingTarget':True},'Each actual statistic follows its own source timing, with no duplicate bonus or save dice.',['DE4-C04'])
    case('locate-creature','One remote bearing and no hidden reason','The caster knows one actual individual T by reliable identity. At resolution T is on the same actual plane three miles away behind ordinary stone, still the same identity after a disguise/body transformation. T has no applicable information protection.', ['The express remote sense ignores originating wall LoE and returns only direction/vertical bearing, not distance, room, route, HP or a visible destination.', 'Separate fixtures at the same read checkpoint replace T with its corpse, an actually source-ended summon, an active Banishment-cell occupant, or a protected subject. Each yields No Bearing under its own actual reason, with no reason disclosed.', 'A later ordinary movement of an eligible T is not tracked. A fresh legal paid cast is needed for a new snapshot.'],base,{'read':'one resolution snapshot','trackingDuration':0},{'eligibleTargetDistanceFeet':15840,'maximumFeet':26400,'ordinaryStoneBlocks':False},'Continuing identity and actual information scope determine the single bearing.',['DE4-C05'])
    case('locate-creature','Ended exile with a placement conflict','T\'s ordinary Banishment cell has actually ended. Physical obstruction prevents every permitted return footprint, so accepted BAN-CONFLICT-04 records T\'s AnchorReference on the original plane one mile from the locator; T is still living and unprotected by an applicable information ward.', ['Apply this spell\'s same-plane range/predicate read to the actual logical AnchorReference and return bearing under its express remote-sense permission.', 'T gains no occupied footprint, adjacency, cover, support, sight, path or successful placement. The locator gains no automatic ordinary attack target or route.', 'T\'s real clocks and independent source-permitted conflict actions continue. Removing the obstruction triggers only the actual accepted placement recheck; this inquiry neither cures nor prolongs the conflict.'],base,{'cellStatus':'ended before inquiry','ordinaryClocks':'continue'},{'referenceDistanceFeet':5280,'occupiedFootprint':False},'Logical source-test location is distinct from physical placement, without inventing untargetability or a body.',['DE4-C05'])
    case('faction-secrets','Established institutional fact versus private thought','Use an actual known canonical faction F; this fixture adds no new faction identity. Director records already contain one nonpublic warehouse relocation order responsive to the caster\'s concrete logistics subject. An officer also has a separately protected private suspicion, not an institutional record.', ['The inquiry returns the established relocation fact, within its actual unprotected content. It does not disclose the officer\'s private suspicion or label which hidden detail was protected.', 'An equivalent logistics inquiry by another caster or rewording under unchanged records returns the same stable selected fact.', 'Learning it grants no membership, standing, alliedStatus, invocation permission, public announcement or power to issue orders.'],base,{'institutionalSnapshot':'current resolution','equivalentQueryKey':'stable until underlying facts change'},{'selfInquiry':'no fictitious60ft representative'},'Useful institutional knowledge is preserved without manufacturing a secret or credential.',['DE4-C06'])
    case('faction-secrets','No responsive secret','The exact known faction exists, but the specified concrete institutional subject has no established responsive nonpublic fact. No member/representative is physically near the caster.', ['Return Indeterminate; the Director does not invent a secret, hidden roster, protected identity or new doctrine to satisfy a paid spell.', 'The source\'s proposed Self inquiry needs no representative, so absence of a nearby member is not separately disclosed or treated as a new range failure.', 'Costs remain spent. A later genuine new established institutional fact may change a later paid answer; rephrasing alone does not.'],base,{'effect':'instantaneous','futureRead':'new actual paid cast'},{'representativeRequired':False},'Missing information stays missing without revealing why.',['DE4-C06'])
    case('alignment-forecast','Known Lock expiry changes a supported interaction','T has underlying LawfulEvil plus an active accepted Lock snapshotNeutralGood expiring t30. A current accepted Alignment Portal took a fixed NeutralGood compatibility snapshot. At t10 T declares a concrete crossing attempt beginning t20, with the goal of reaching its known destination; all other needed facts are established/unprotected.', ['For the t20 alignment contribution, T\'s effective pair is NeutralGood under AC4-ALIGN-01 despite the underlying pair; the portal\'s immutable snapshot is NeutralGood. The alignment contribution is Favored.', 'For a genuinely different planned crossing beginning t40 after the known Lock expiry, effective T is LawfulEvil absent another actual overlay, while the portal snapshot remains NeutralGood. If that is a live portal then, the alignment contribution is Opposed.', 'Neither answer promises total success or discloses axes, portal coordinates, motives or hidden causal details. If the portal actually expires before40, its real expiry must be considered rather than pretending it remains live.'],base,{'inquiry':10,'lockEnd':30,'distinctPlanBeginnings':[20,40]},{'TPerceivedWithin60':True},'The forecast uses actual source timing and distinguishes snapshot compatibility from live alignment.',['DE4-C07'])
